INSERT INTO layout_searches (
    baseline_simulation_id, baseline_layout_version_id, planner_version, status,
    baseline_metrics, diagnosis, budget, constraints, requested_by
) VALUES (
    #{baselineSimulationId}, #{baselineLayoutVersionId}, #{plannerVersion}, #{status},
    #{baselineMetrics}, #{diagnosis}, #{budget}, #{constraints}, #{requestedBy}
)

mapper.update:
UPDATE layout_searches
SET status = 'DIAGNOSING', started_at = #{startedAt}
WHERE id = #{id}
  AND status = 'PENDING'

UPDATE layout_searches
SET diagnosis = #{diagnosis}
WHERE id = #{id}

UPDATE layout_searches
SET status = #{status}
WHERE id = #{id}
  AND status IN ('PENDING', 'DIAGNOSING', 'GENERATING', 'VERIFYING')

UPDATE layout_searches
SET planner_version = #{plannerVersion}
WHERE id = #{id}
  AND status IN ('PENDING', 'DIAGNOSING', 'GENERATING', 'VERIFYING')

UPDATE layout_searches
SET status = #{status}, finished_at = #{finishedAt},
    failure_code = #{failureCode}, failure_message = #{failureMessage}
WHERE id = #{id}
  AND status IN ('PENDING', 'DIAGNOSING', 'GENERATING', 'VERIFYING')

mapper.insert:
INSERT INTO layout_search_candidates (
    study_id, parent_candidate_id, round_index, candidate_order,
    origin_finding_type, operator_type, status, change_set, rationale, proxy_score, reject_reason, constraints_snapshot
) SELECT
    #{studyId}, #{parentCandidateId}, #{roundIndex}, #{candidateOrder},
    #{originFindingType}, #{operatorType}, #{status}, #{changeSet}, #{rationale}, #{proxyScore}, #{rejectReason}, #{constraintsSnapshot}
FROM layout_searches
WHERE id = #{studyId}
  AND status IN ('PENDING', 'DIAGNOSING', 'GENERATING', 'VERIFYING')

mapper.update:
UPDATE layout_search_candidates
SET status = #{status}, reject_reason = #{rejectReason}
WHERE id = #{id}
  AND status = 'RUNNING'

UPDATE layout_search_candidates
SET metric_delta = #{metricDelta}
WHERE id = #{id}

UPDATE layout_search_candidates
SET adopted_layout_version_id = #{layoutVersionId},
    prepared_simulation_id = #{simulationId},
    adopted_at = #{adoptedAt}
WHERE id = #{id}

UPDATE layout_search_candidates
SET status = 'FAILED', reject_reason = #{rejectReason}
WHERE study_id = #{searchId}
  AND status IN ('QUEUED', 'RUNNING')

UPDATE layout_search_trials
SET engine_version = #{engineVersion}, termination_reason = #{terminationReason},
    metrics = #{metrics}, total_move_distance = #{totalMoveDistance}, finished_at = #{finishedAt}, failure_message = #{failureMessage}
WHERE id = #{id}
  AND finished_at IS NULL
